svg.script:
const ns="http://www.w3.org/2000/svg";
// internal ring teeth
const rt=document.getElementById("ringteeth");
for(let i=0;i<24;i++){const a=i/24*2*Math.PI;
  const l=document.createElementNS(ns,"line");
  l.setAttribute("x1",Math.cos(a)*85);l.setAttribute("y1",Math.sin(a)*85);
  l.setAttribute("x2",Math.cos(a)*77);l.setAttribute("y2",Math.sin(a)*77);
  l.setAttribute("stroke-width","3");l.setAttribute("opacity","0.7");rt.appendChild(l);}
// bearing balls
const balls=document.getElementById("balls");
for(let i=0;i<8;i++){const a=i/8*2*Math.PI - Math.PI/2;
  const c=document.createElementNS(ns,"circle");
  c.setAttribute("cx",(Math.cos(a)*55).toFixed(1));
  c.setAttribute("cy",(Math.sin(a)*55).toFixed(1));
  c.setAttribute("r","9");balls.appendChild(c);}
// outer gear ring (16 trapezoid teeth) for C
function gp(N,ri,ro){const s=2*Math.PI/N,P=(a,r)=>`${(Math.cos(a)*r).toFixed(2)},${(Math.sin(a)*r).toFixed(2)}`;
  let d="";for(let i=0;i<N;i++){const a0=i*s,a1=a0+s*0.4,a2=a0+s*0.5,a3=a0+s*0.9,a4=a0+s;
  if(i===0)d+=`M ${P(a0,ri)} `;d+=`L ${P(a0,ro)} L ${P(a1,ro)} L ${P(a2,ri)} L ${P(a3,ri)} L ${P(a4,ri)} `;}return d+"Z";}
document.getElementById("cgear").setAttribute("d",gp(16,64,80));
